namespace fs = std::filesystem;

static uint64_t fnv1a64(const void* data, size_t bytes) {
    const auto* pointer =
        static_cast<const uint8_t*>(data);
    uint64_t value = 1469598103934665603ull;
    for (size_t index = 0; index < bytes; ++index) {
        value ^= pointer[index];
        value *= 1099511628211ull;
    }
    return value;
}

static std::vector<uint8_t> read_bytes(
    const fs::path& path) {
    std::ifstream stream(path, std::ios::binary);
    if (!stream) {
        throw std::runtime_error(
            "failed to open: " + path.string());
    }
    stream.seekg(0, std::ios::end);
    const std::streamoff size = stream.tellg();
    stream.seekg(0, std::ios::beg);
    if (size < 0) {
        throw std::runtime_error(
            "failed to size: " + path.string());
    }

    std::vector<uint8_t> data(
        static_cast<size_t>(size));
    if (!data.empty()) {
        stream.read(
            reinterpret_cast<char*>(data.data()),
            static_cast<std::streamsize>(data.size()));
    }
    if (!stream.good() && !stream.eof()) {
        throw std::runtime_error(
            "failed to read: " + path.string());
    }
    return data;
}

static std::string read_text(
    const fs::path& path) {
    const std::vector<uint8_t> data =
        read_bytes(path);
    return std::string(
        reinterpret_cast<const char*>(data.data()),
        data.size());
}

static void write_bytes(
    const fs::path& path,
    const void* data,
    size_t bytes) {
    std::ofstream stream(path, std::ios::binary);
    if (!stream) {
        throw std::runtime_error(
            "failed to open for write: " +
            path.string());
    }
    stream.write(
        static_cast<const char*>(data),
        static_cast<std::streamsize>(bytes));
    if (!stream.good()) {
        throw std::runtime_error(
            "failed to write: " + path.string());
    }
}

static void write_text(
    const fs::path& path,
    const std::string& text) {
    write_bytes(path, text.data(), text.size());
}

static void append_utf8(
    std::string& output,
    uint32_t codepoint) {
    if (codepoint <= 0x7Fu) {
        output.push_back(
            static_cast<char>(codepoint));
    } else if (codepoint <= 0x7FFu) {
        output.push_back(
            static_cast<char>(
                0xC0u | (codepoint >> 6)));
        output.push_back(
            static_cast<char>(
                0x80u | (codepoint & 0x3Fu)));
    } else if (codepoint <= 0xFFFFu) {
        output.push_back(
            static_cast<char>(
                0xE0u | (codepoint >> 12)));
        output.push_back(
            static_cast<char>(
                0x80u |
                ((codepoint >> 6) & 0x3Fu)));
        output.push_back(
            static_cast<char>(
                0x80u | (codepoint & 0x3Fu)));
    } else if (codepoint <= 0x10FFFFu) {
        output.push_back(
            static_cast<char>(
                0xF0u | (codepoint >> 18)));
        output.push_back(
            static_cast<char>(
                0x80u |
                ((codepoint >> 12) & 0x3Fu)));
        output.push_back(
            static_cast<char>(
                0x80u |
                ((codepoint >> 6) & 0x3Fu)));
        output.push_back(
            static_cast<char>(
                0x80u | (codepoint & 0x3Fu)));
    } else {
        throw std::runtime_error(
            "invalid Unicode codepoint");
    }
}

static uint32_t parse_hex4(
    const std::string& text,
    size_t position) {
    if (position + 4 > text.size()) {
        throw std::runtime_error(
            "short JSON Unicode escape");
    }
    uint32_t value = 0;
    for (size_t offset = 0; offset < 4; ++offset) {
        const char c = text[position + offset];
        value <<= 4;
        if (c >= '0' && c <= '9') {
            value |= static_cast<uint32_t>(
                c - '0');
        } else if (c >= 'a' && c <= 'f') {
            value |= static_cast<uint32_t>(
                c - 'a' + 10);
        } else if (c >= 'A' && c <= 'F') {
            value |= static_cast<uint32_t>(
                c - 'A' + 10);
        } else {
            throw std::runtime_error(
                "invalid JSON Unicode escape");
        }
    }
    return value;
}

class VocabularyParser {
public:
    explicit VocabularyParser(
        std::string text)
        : text_(std::move(text)) {}

    std::unordered_map<std::string, int64_t>
    parse() {
        skip_space();
        require('{');

        std::unordered_map<std::string, int64_t>
            vocabulary;
        vocabulary.reserve(160000);
        skip_space();
        if (consume('}')) {
            return vocabulary;
        }

        for (;;) {
            const std::string token =
                parse_string();
            skip_space();
            require(':');
            skip_space();
            const int64_t id = parse_integer();

            vocabulary.emplace(token, id);

            skip_space();
            if (consume('}')) {
                break;
            }
            require(',');
        }

        skip_space();
        if (position_ != text_.size()) {
            fail("trailing JSON data");
        }
        return vocabulary;
    }

private:

    std::string text_;
    size_t position_ = 0;

    [[noreturn]] void fail(
        const std::string& message) const {
        throw std::runtime_error(
            "vocab JSON error at byte " +
            std::to_string(position_) +
            ": " + message);
    }

    void skip_space() {
        while (position_ < text_.size()) {
            const char c = text_[position_];
            if (c == ' ' ||
                c == '\n' ||
                c == '\r' ||
                c == '\t') {
                ++position_;
            } else {
                break;
            }
        }
    }

    bool consume(char expected) {
        skip_space();
        if (position_ < text_.size() &&
            text_[position_] == expected) {
            ++position_;
            return true;
        }
        return false;
    }

    void require(char expected) {
        if (!consume(expected)) {
            fail(
                std::string("expected '") +
                expected + "'");
        }
    }

    std::string parse_string() {
        skip_space();
        if (position_ >= text_.size() ||
            text_[position_] != '"') {
            fail("expected string");
        }
        ++position_;

        std::string output;
        while (position_ < text_.size()) {
            const unsigned char c =
                static_cast<unsigned char>(
                    text_[position_++]);

            if (c == '"') {
                return output;
            }

            if (c != '\\') {
                output.push_back(
                    static_cast<char>(c));
                continue;
            }

            if (position_ >= text_.size()) {
                fail("unfinished escape");
            }

            const char escaped =
                text_[position_++];
            switch (escaped) {
                case '"':
                case '\\':
                case '/':
                    output.push_back(escaped);
                    break;
                case 'b':
                    output.push_back('\b');
                    break;
                case 'f':
                    output.push_back('\f');
                    break;
                case 'n':
                    output.push_back('\n');
                    break;
                case 'r':
                    output.push_back('\r');
                    break;
                case 't':
                    output.push_back('\t');
                    break;
                case 'u': {
                    const uint32_t first =
                        parse_hex4(
                            text_, position_);
                    position_ += 4;

                    uint32_t codepoint = first;
                    if (first >= 0xD800u &&
                        first <= 0xDBFFu) {
                        if (position_ + 6 >
                                text_.size() ||
                            text_[position_] != '\\' ||
                            text_[position_ + 1] != 'u') {
                            fail(
                                "missing low surrogate");
                        }
                        position_ += 2;
                        const uint32_t second =
                            parse_hex4(
                                text_, position_);
                        position_ += 4;
                        if (second < 0xDC00u ||
                            second > 0xDFFFu) {
                            fail(
                                "invalid low surrogate");
                        }
                        codepoint =
                            0x10000u +
                            ((first - 0xD800u) << 10) +
                            (second - 0xDC00u);
                    } else if (
                        first >= 0xDC00u &&
                        first <= 0xDFFFu) {
                        fail(
                            "unexpected low surrogate");
                    }
                    append_utf8(
                        output, codepoint);
                    break;
                }
                default:
                    fail("unknown escape");
            }
        }

        fail("unterminated string");
    }

    int64_t parse_integer() {
        skip_space();
        const size_t begin = position_;
        bool negative = false;
        if (position_ < text_.size() &&
            text_[position_] == '-') {
            negative = true;
            ++position_;
        }

        uint64_t value = 0;
        size_t digits = 0;
        while (position_ < text_.size() &&
               std::isdigit(
                   static_cast<unsigned char>(
                       text_[position_]))) {
            value =
                value * 10u +
                static_cast<uint64_t>(
                    text_[position_] - '0');
            ++position_;
            ++digits;
        }

        if (digits == 0) {
            position_ = begin;
            fail("expected integer");
        }

        if (!negative &&
            value >
                static_cast<uint64_t>(
                    std::numeric_limits<int64_t>::
                        max())) {
            fail("integer overflow");
        }

        if (negative) {
            if (value >
                static_cast<uint64_t>(
                    std::numeric_limits<int64_t>::
                        max()) + 1u) {
                fail("integer overflow");
            }
            return -static_cast<int64_t>(value);
        }
        return static_cast<int64_t>(value);
    }
};

