namespace fs = std::filesystem;

static constexpr size_t ZIMAGE_NOISE_ELEMENTS =
    static_cast<size_t>(1) * 16 * 128 * 128;

static uint64_t fnv1a64(
    const void* data,
    size_t bytes) {
    const auto* pointer =
        static_cast<const uint8_t*>(data);
    uint64_t value = 1469598103934665603ull;
    for (size_t index = 0;
         index < bytes;
         ++index) {
        value ^= pointer[index];
        value *= 1099511628211ull;
    }
    return value;
}

static uint64_t parse_u64(
    const std::string& text) {
    if (text.empty() || text[0] == '-') {
        throw std::runtime_error(
            "seed must be an unsigned 64-bit integer");
    }

    size_t consumed = 0;
    unsigned long long value = 0;
    try {
        value = std::stoull(
            text,
            &consumed,
            0);
    } catch (const std::exception&) {
        throw std::runtime_error(
            "invalid uint64 seed: " + text);
    }
    if (consumed != text.size()) {
        throw std::runtime_error(
            "invalid trailing characters in seed: " +
            text);
    }
    return static_cast<uint64_t>(value);
}

static void write_binary(
    const fs::path& path,
    const void* data,
    size_t bytes) {
    if (!path.parent_path().empty()) {
        fs::create_directories(
            path.parent_path());
    }
    std::ofstream stream(
        path,
        std::ios::binary);
    if (!stream) {
        throw std::runtime_error(
            "failed to open output: " +
            path.string());
    }
    stream.write(
        static_cast<const char*>(data),
        static_cast<std::streamsize>(bytes));
    if (!stream.good()) {
        throw std::runtime_error(
            "failed to write output: " +
            path.string());
    }
}

static std::vector<uint8_t> read_binary(
    const fs::path& path) {
    std::ifstream stream(
        path,
        std::ios::binary);
    if (!stream) {
        throw std::runtime_error(
            "failed to open reference: " +
            path.string());
    }
    stream.seekg(0, std::ios::end);
    const std::streamoff size =
        stream.tellg();
    stream.seekg(0, std::ios::beg);
    if (size < 0) {
        throw std::runtime_error(
            "failed to size reference: " +
            path.string());
    }

    std::vector<uint8_t> data(
        static_cast<size_t>(size));
    if (!data.empty()) {
        stream.read(
            reinterpret_cast<char*>(
                data.data()),
            static_cast<std::streamsize>(
                data.size()));
    }
    if (!stream.good() &&
        !stream.eof()) {
        throw std::runtime_error(
            "failed to read reference: " +
            path.string());
    }
    return data;
}

class NumpySeedSequenceU64 {
public:
    static std::array<uint64_t, 4>
    generate_state(uint64_t seed) {
        std::vector<uint32_t> entropy;
        entropy.reserve(2);
        entropy.push_back(
            static_cast<uint32_t>(seed));
        const uint32_t high =
            static_cast<uint32_t>(
                seed >> 32);
        if (high != 0) {
            entropy.push_back(high);
        }

        std::array<uint32_t, 4> pool{};
        uint32_t hash_constant = INIT_A;

        for (size_t index = 0;
             index < pool.size();
             ++index) {
            pool[index] =
                hashmix(
                    index < entropy.size()
                        ? entropy[index]
                        : 0u,
                    hash_constant);
        }

        for (size_t source = 0;
             source < pool.size();
             ++source) {
            for (size_t destination = 0;
                 destination < pool.size();
                 ++destination) {
                if (source == destination) {
                    continue;
                }
                pool[destination] =
                    mix(
                        pool[destination],
                        hashmix(
                            pool[source],
                            hash_constant));
            }
        }

        for (size_t source = pool.size();
             source < entropy.size();
             ++source) {
            for (size_t destination = 0;
                 destination < pool.size();
                 ++destination) {
                pool[destination] =
                    mix(
                        pool[destination],
                        hashmix(
                            entropy[source],
                            hash_constant));
            }
        }

        std::array<uint32_t, 8> words{};
        hash_constant = INIT_B;

        for (size_t index = 0;
             index < words.size();
             ++index) {
            uint32_t value =
                pool[index % pool.size()];
            value ^= hash_constant;
            hash_constant *= MULT_B;
            value *= hash_constant;
            value ^= value >> XSHIFT;
            words[index] = value;
        }

        std::array<uint64_t, 4> result{};
        for (size_t index = 0;
             index < result.size();
             ++index) {

            result[index] =
                static_cast<uint64_t>(
                    words[index * 2]) |
                (static_cast<uint64_t>(
                     words[index * 2 + 1])
                 << 32);
        }
        return result;
    }

private:
    static constexpr uint32_t INIT_A =
        0x43b0d7e5u;
    static constexpr uint32_t MULT_A =
        0x931e8875u;
    static constexpr uint32_t INIT_B =
        0x8b51f9ddu;
    static constexpr uint32_t MULT_B =
        0x58f38dedu;
    static constexpr uint32_t MIX_MULT_L =
        0xca01f9ddu;
    static constexpr uint32_t MIX_MULT_R =
        0x4973f715u;
    static constexpr uint32_t XSHIFT = 16u;

    static uint32_t hashmix(
        uint32_t value,
        uint32_t& hash_constant) {
        value ^= hash_constant;
        hash_constant *= MULT_A;
        value *= hash_constant;
        value ^= value >> XSHIFT;
        return value;
    }

    static uint32_t mix(
        uint32_t left,
        uint32_t right) {
        uint32_t result =
            MIX_MULT_L * left -
            MIX_MULT_R * right;
        result ^= result >> XSHIFT;
        return result;
    }
};

class NumpyPcg64 {
public:
    explicit NumpyPcg64(
        uint64_t seed) {
        const std::array<uint64_t, 4>
            generated =
                NumpySeedSequenceU64::
                    generate_state(seed);

        const uint128_t initial_state =
            (static_cast<uint128_t>(
                 generated[0])
             << 64) |
            generated[1];
        const uint128_t initial_sequence =
            (static_cast<uint128_t>(
                 generated[2])
             << 64) |
            generated[3];

        state_ = 0;
        increment_ =
            (initial_sequence << 1) | 1;
        step();
        state_ += initial_state;
        step();
    }

    uint32_t next_uint32() {
        if (has_uint32_) {
            has_uint32_ = false;
            return buffered_uint32_;
        }

        const uint64_t value =
            next_uint64();
        has_uint32_ = true;
        buffered_uint32_ =
            static_cast<uint32_t>(
                value >> 32);
        return static_cast<uint32_t>(
            value);
    }

    float next_float() {
        return
            static_cast<float>(
                next_uint32() >> 8) *
            (1.0f / 16777216.0f);
    }

    float standard_normal_float() {
        for (;;) {
            const uint32_t random =
                next_uint32();
            const int index =
                static_cast<int>(
                    random & 0xffu);
            const int sign =
                static_cast<int>(
                    (random >> 8) & 1u);
            const uint32_t absolute =
                (random >> 9) &
                0x007fffffu;

            float value =
                static_cast<float>(
                    absolute) *
                wi_float[index];

            if (sign != 0) {
                value = -value;
            }

            if (absolute <
                ki_float[index]) {
                return value;
            }

            if (index == 0) {
                for (;;) {
                    const float xx =
                        -ziggurat_nor_inv_r_f *
                        ::log1pf(
                            -next_float());
                    const float yy =
                        -::log1pf(
                            -next_float());

                    if (yy + yy >
                        xx * xx) {
                        return
                            ((absolute >> 8) &
                             1u)
                                ? -(
                                    ziggurat_nor_r_f +
                                    xx)
                                : ziggurat_nor_r_f +
                                    xx;
                    }
                }
            }

            const double left =
                static_cast<double>(
                    (fi_float[index - 1] -
                     fi_float[index]) *
                        next_float() +
                    fi_float[index]);
            const double right =
                ::exp(
                    -0.5 *
                    static_cast<double>(
                        value) *
                    static_cast<double>(
                        value));

            if (left < right) {
                return value;
            }
        }
    }

private:
    using uint128_t =
        unsigned __int128;

    static constexpr uint64_t
        MULTIPLIER_HIGH =
            2549297995355413924ull;
    static constexpr uint64_t
        MULTIPLIER_LOW =
            4865540595714422341ull;

    uint128_t state_ = 0;
    uint128_t increment_ = 0;
    bool has_uint32_ = false;
    uint32_t buffered_uint32_ = 0;

    static uint128_t multiplier() {
        return
            (static_cast<uint128_t>(
                 MULTIPLIER_HIGH)
             << 64) |
            MULTIPLIER_LOW;
    }

    static uint64_t rotate_right(
        uint64_t value,
        unsigned rotation) {
        return
            (value >> rotation) |
            (value <<
             ((-rotation) & 63u));
    }

    void step() {
        state_ =
            state_ * multiplier() +
            increment_;
    }

    uint64_t next_uint64() {

        step();

        const uint64_t high =
            static_cast<uint64_t>(
                state_ >> 64);
        const uint64_t low =
            static_cast<uint64_t>(
                state_);

        return rotate_right(
            high ^ low,
            static_cast<unsigned>(
                state_ >> 122));
    }
};

struct CompareResult {
    size_t exact = 0;
    size_t count = 0;
    size_t first_mismatch = 0;
    double max_abs = 0.0;
    long double sum_abs = 0.0;
    long double sum_sq = 0.0;
};

static CompareResult compare_float_bits(
    const std::vector<float>& actual,
    const fs::path& reference_path) {
    const std::vector<uint8_t> bytes =
        read_binary(reference_path);
    const size_t expected_bytes =
        actual.size() *
        sizeof(float);
    if (bytes.size() != expected_bytes) {
        throw std::runtime_error(
            "reference noise size mismatch: expected " +
            std::to_string(expected_bytes) +
            " bytes, got " +
            std::to_string(bytes.size()));
    }

    CompareResult result;
    result.count = actual.size();
    result.first_mismatch =
        actual.size();

    for (size_t index = 0;
         index < actual.size();
         ++index) {
        uint32_t actual_bits = 0;
        uint32_t expected_bits = 0;
        std::memcpy(
            &actual_bits,
            &actual[index],
            sizeof(uint32_t));
        std::memcpy(
            &expected_bits,
            bytes.data() +
                index * sizeof(uint32_t),
            sizeof(uint32_t));

        float expected_value = 0.0f;
        std::memcpy(
            &expected_value,
            &expected_bits,
            sizeof(float));

        if (actual_bits ==
            expected_bits) {
            ++result.exact;
        } else if (
            result.first_mismatch ==
            actual.size()) {
            result.first_mismatch =
                index;
        }

        const double difference =
            std::abs(
                static_cast<double>(
                    actual[index]) -
                static_cast<double>(
                    expected_value));
        result.max_abs =
            std::max(
                result.max_abs,
                difference);
        result.sum_abs += difference;
        result.sum_sq +=
            difference * difference;
    }
    return result;
}

int noise_stage_main(int argc, char** argv) {
    try {
        uint64_t seed = 42;
        size_t count =
            ZIMAGE_NOISE_ELEMENTS;
        fs::path output =
            "initial_noise_1x16x128x128.f32";
        fs::path metadata;
        fs::path compare_path;

        for (int index = 1;
             index < argc;
             ++index) {
            const std::string argument =
                argv[index];

            auto require_value =
                [&](std::string& value) {
                    if (index + 1 >= argc) {
                        throw std::runtime_error(
                            "missing value for " +
                            argument);
                    }
                    value = argv[++index];
                };

            if (argument == "--seed") {
                std::string value;
                require_value(value);
                seed = parse_u64(value);
            } else if (
                argument == "--count") {
                std::string value;
                require_value(value);
                count =
                    static_cast<size_t>(
                        parse_u64(value));
            } else if (
                argument == "--out") {
                std::string value;
                require_value(value);
                output = value;
            } else if (
                argument == "--meta") {
                std::string value;
                require_value(value);
                metadata = value;
            } else if (
                argument == "--compare") {
                std::string value;
                require_value(value);
                compare_path = value;
            } else if (
                argument == "--help" ||
                argument == "-h") {
                std::cout
                    << "Usage: "
                    << argv[0]
                    << " [--seed UINT64]"
                    << " [--count N]"
                    << " [--out noise.f32]"
                    << " [--meta meta.txt]"
                    << " [--compare reference.f32]\n";
                return 0;
            } else {
                throw std::runtime_error(
                    "unknown argument: " +
                    argument);
            }
        }

        if (count == 0) {
            throw std::runtime_error(
                "count must be positive");
        }

        NumpyPcg64 generator(seed);
        std::vector<float> noise(count);

        double minimum =
            std::numeric_limits<double>::
                max();
        double maximum =
            -std::numeric_limits<double>::
                max();
        long double sum = 0.0;
        long double sum_sq = 0.0;

        for (size_t index = 0;
             index < count;
             ++index) {
            const float value =
                generator.standard_normal_float();
            noise[index] = value;
            minimum =
                std::min(
                    minimum,
                    static_cast<double>(
                        value));
            maximum =
                std::max(
                    maximum,
                    static_cast<double>(
                        value));
            sum += value;
            sum_sq +=
                static_cast<long double>(
                    value) *
                value;
        }

        write_binary(
            output,
            noise.data(),
            noise.size() *
                sizeof(float));

        const uint64_t hash =
            fnv1a64(
                noise.data(),
                noise.size() *
                    sizeof(float));
        const double mean =
            static_cast<double>(
                sum /
                static_cast<long double>(
                    count));
        const double rms =
            std::sqrt(
                static_cast<double>(
                    sum_sq /
                    static_cast<long double>(
                        count)));

        std::cout
            << "[NATIVE NUMPY-PCG64 NOISE COMPLETE]\n"
            << "algorithm=NumPy PCG64 + float32 Ziggurat\n"
            << "seed="
            << seed << "\n"
            << "count="
            << count << "\n"
            << "shape="
            << (count ==
                    ZIMAGE_NOISE_ELEMENTS
                    ? "1x16x128x128"
                    : "flat")
            << "\n"
            << std::setprecision(10)
            << "min="
            << minimum << "\n"
            << "max="
            << maximum << "\n"
            << "mean="
            << mean << "\n"
            << "rms="
            << rms << "\n"
            << "fnv64=0x"
            << std::hex
            << std::setw(16)
            << std::setfill('0')
            << hash
            << std::dec
            << std::setfill(' ')
            << "\n"
            << "output="
            << output << "\n";

        if (!compare_path.empty()) {
            const CompareResult comparison =
                compare_float_bits(
                    noise,
                    compare_path);
            const double mean_abs =
                comparison.count
                    ? static_cast<double>(
                        comparison.sum_abs /
                        static_cast<long double>(
                            comparison.count))
                    : 0.0;
            const double compare_rms =
                comparison.count
                    ? std::sqrt(
                        static_cast<double>(
                            comparison.sum_sq /
                            static_cast<long double>(
                                comparison.count)))
                    : 0.0;

            std::cout
                << "[compare] exact="
                << comparison.exact
                << "/"
                << comparison.count
                << " ("
                << 100.0 *
                    static_cast<double>(
                        comparison.exact) /
                    static_cast<double>(
                        comparison.count)
                << "%)"
                << " max_abs="
                << comparison.max_abs
                << " mean_abs="
                << mean_abs
                << " rms="
                << compare_rms
                << "\n";

            if (comparison.exact !=
                comparison.count) {
                std::cerr
                    << "[compare] first mismatch index="
                    << comparison.first_mismatch
                    << "\n";
                return 3;
            }
        }

        if (!metadata.empty()) {
            if (!metadata.parent_path().empty()) {
                fs::create_directories(
                    metadata.parent_path());
            }
            std::ofstream stream(metadata);
            if (!stream) {
                throw std::runtime_error(
                    "failed to open metadata: " +
                    metadata.string());
            }
            stream
                << "algorithm=numpy_pcg64_standard_normal_float32\n"
                << "seed="
                << seed << "\n"
                << "count="
                << count << "\n"
                << "shape="
                << (count ==
                        ZIMAGE_NOISE_ELEMENTS
                        ? "1x16x128x128"
                        : "flat")
                << "\n"
                << "fnv64=0x"
                << std::hex
                << std::setw(16)
                << std::setfill('0')
                << hash
                << std::dec
                << "\n"
                << "output="
                << output.string()
                << "\n";
        }

        return 0;
    } catch (const std::exception& error) {
        std::cerr
            << "FATAL: "
            << error.what()
            << "\n";
        return 1;
    }
}

