                    z35a_head_major_offset(
                        row,
                        column,
                        rows);
                q_output[
                    offset] =
                    hip_bfloat16(
                        q_accumulator[
                            element]);
                k_output[
                    offset] =
                    hip_bfloat16(
                        k_accumulator[
                            element]);
                v_output[
                    offset] =
                    hip_bfloat16(
                        v_accumulator[
                            element]);
