            const int next_k = (tile + 1) * K_TILE;
            const bool has_next = tile + 1 < k_tiles;

            z6_v16s next_a = {};
            z6_v16s next_q = {};
            z6_v16s next_k_weight = {};
            z6_v16s next_v = {};

