                const int local_row =
                    thread / K_VECTORS;
                const int local_vector =
                    thread % K_VECTORS;
                const int global_row =
                    block_m + local_row;
                const int global_k =
                    next_k + local_vector * 16;
                const int valid =
                    global_row < rows
                        ? z33_valid16(
                              reduction_columns -
                              global_k)
                        : 0;
                next_a =
                    z33_load_bf16x16(
                        valid > 0
                            ? input +
                                  static_cast<uint64_t>(
                                      global_row) *
                                      reduction_columns +
                                  global_k
                            : nullptr,
                        valid);

                const int local_column =
                    thread / K_VECTORS;
                const int global_column =
                    block_n + local_column;
                const int valid_w =
                    global_column < columns
                        ? z33_valid16(
                              reduction_columns -
                              global_k)
                        : 0;
                const uint64_t offset =
                    valid_w > 0
                        ? static_cast<uint64_t>(
                              global_column) *
                              reduction_columns +
                          global_k
                        : 0;

                next_q =
                    z33_load_bf16x16(
                        valid_w > 0
                            ? q_weight + offset
                            : nullptr,
                        valid_w);
                next_k_weight =
                    z33_load_bf16x16(
                        valid_w > 0
                            ? k_weight + offset
                            : nullptr,
                        valid_w);
                next_v =
                    z33_load_bf16x16(
                        valid_w > 0
                            ? v_weight + offset
                            : nullptr,
                        valid_w);
