enum class ZQuantType : uint32_t {
    Q8_0 = 8,
    Q5_K = 13,
    Q6_K = 14,
};

struct ZQ8DeviceWeightInfo {
    ZQuantType type = ZQuantType::Q8_0;
    int output_columns = 0;
    int reduction_columns = 0;
    size_t storage_bytes = 0;
};

static std::unordered_map<
    const void*,
    ZQ8DeviceWeightInfo>
    zq8_device_weight_registry;

static size_t zq8_device_weight_count_flag = 0;
static size_t zq8_device_q8_0_count_flag = 0;
static size_t zq8_device_q5_k_count_flag = 0;
static size_t zq8_device_q6_k_count_flag = 0;
static size_t zq8_device_weight_bytes_flag = 0;
static bool zq8_linear_used_flag = false;
static bool zq8_reference_bf16_used_flag = false;

static void zq8_register_device_weight(
    const ZQ8DeviceWeightInfo& info) {
    ++zq8_device_weight_count_flag;
    zq8_device_weight_bytes_flag +=
        info.storage_bytes;
    if (info.type == ZQuantType::Q5_K) {
        ++zq8_device_q5_k_count_flag;
    } else if (info.type == ZQuantType::Q6_K) {
        ++zq8_device_q6_k_count_flag;
    } else {
        ++zq8_device_q8_0_count_flag;
    }
}

static void zq8_unregister_device_weight(
    const ZQ8DeviceWeightInfo& info) {
    if (zq8_device_weight_count_flag > 0) {
        --zq8_device_weight_count_flag;
    }
    if (zq8_device_weight_bytes_flag >=
        info.storage_bytes) {
        zq8_device_weight_bytes_flag -=
            info.storage_bytes;
    }
    if (info.type == ZQuantType::Q5_K) {
        if (zq8_device_q5_k_count_flag > 0) {
            --zq8_device_q5_k_count_flag;
        }
    } else if (info.type == ZQuantType::Q6_K) {
        if (zq8_device_q6_k_count_flag > 0) {
            --zq8_device_q6_k_count_flag;
        }
    } else if (zq8_device_q8_0_count_flag > 0) {
        --zq8_device_q8_0_count_flag;
    }
}

static hip_bfloat16*
    zq8_reference_bf16_scratch[2] = {
        nullptr,
        nullptr,
    };
static size_t
    zq8_reference_bf16_scratch_bytes = 0;
static hipStream_t
    zq8_decode_stream = nullptr;
static hipEvent_t
    zq8_pipeline_fork_event = nullptr;
static hipEvent_t
    zq8_pipeline_ready_event[2] = {
        nullptr,
        nullptr,
    };
static hipEvent_t
    zq8_pipeline_free_event[2] = {
        nullptr,
        nullptr,
    };
static constexpr int
    zq8_static_quant_op_count = 1920;
static int
    zq8_pipeline_capture_op_index = 0;
static bool
    zq8_pipeline_decode_stream_joined = false;

static constexpr bool zq8_reference_bf16_enabled() {
    return true;
}

static void zq8_bind_reference_bf16_pipeline(
    void* pointer0,
    void* pointer1,
    size_t bytes,
    hipStream_t decode_stream,
    hipEvent_t fork_event,
    hipEvent_t ready_event0,
    hipEvent_t ready_event1,
    hipEvent_t free_event0,
    hipEvent_t free_event1) {
    zq8_reference_bf16_scratch[0] =
        static_cast<hip_bfloat16*>(
            pointer0);
    zq8_reference_bf16_scratch[1] =
        static_cast<hip_bfloat16*>(
            pointer1);
    zq8_reference_bf16_scratch_bytes =
        bytes;
    zq8_decode_stream =
        decode_stream;
    zq8_pipeline_fork_event =
        fork_event;
    zq8_pipeline_ready_event[0] =
        ready_event0;
    zq8_pipeline_ready_event[1] =
        ready_event1;
    zq8_pipeline_free_event[0] =
        free_event0;
    zq8_pipeline_free_event[1] =
        free_event1;
}

static void zq8_begin_async_pipeline_capture() {
    zq8_pipeline_capture_op_index = 0;
    zq8_pipeline_decode_stream_joined =
        false;
}

static void zq8_finalize_static_pipeline_capture() {
    if (zq8_pipeline_capture_op_index !=
        zq8_static_quant_op_count) {
        throw std::runtime_error(
            "static quant decode schedule mismatch: expected " +
            std::to_string(
                zq8_static_quant_op_count) +
            ", captured " +
            std::to_string(
                zq8_pipeline_capture_op_index));
    }
}

static constexpr int
zq8_static_pipeline_op_count() {
    return
        zq8_static_quant_op_count;
}

static void zq8_join_decode_stream_to_capture() {
    if (zq8_pipeline_decode_stream_joined) {
        return;
    }
    if (!zq8_decode_stream ||
        !zq8_pipeline_fork_event) {
        throw std::runtime_error(
            "quant decode stream is not bound");
    }
    HIP_CHECK(
        hipEventRecord(
            zq8_pipeline_fork_event,
            active_sampler_stream));
    HIP_CHECK(
        hipStreamWaitEvent(
            zq8_decode_stream,
            zq8_pipeline_fork_event,
            0));
    zq8_pipeline_decode_stream_joined =
        true;
}

