                    *reinterpret_cast<
                        const z6_v16s*>(
                        &shared_a[
                            current_buffer][
                            local_a_row0 *
                                K_TILE +
                            sub_k]);
                const z6_v16s a_fragment1 =
                    *reinterpret_cast<
                        const z6_v16s*>(
                        &shared_a[
                            current_buffer][
                            local_a_row1 *
                                K_TILE +
                            sub_k]);
                const z6_v16s gate_fragment =
                    *reinterpret_cast<
                        const z6_v16s*>(
                        &shared_gate[
                            current_buffer][
                            local_b_column *
                                K_TILE +
                            sub_k]);
