    z6_v8f32 accumulator01 = {0.0f};
    z6_v8f32 accumulator10 = {0.0f};
    z6_v8f32 accumulator11 = {0.0f};

    z6_v16s* shared_a_vectors =
        reinterpret_cast<z6_v16s*>(
            shared_a);
