static std::string q22_mib(
    size_t bytes) {
    std::ostringstream stream;
    stream
        << std::fixed
        << std::setprecision(2)
        << static_cast<double>(bytes) /
            (1024.0 * 1024.0);
    return stream.str();
}

static constexpr int Q22_OUTPUT_HEIGHT =
    zimage_vae_512x512::Z11_HEIGHT * 8;
static constexpr int Q22_OUTPUT_WIDTH =
    zimage_vae_512x512::Z11_WIDTH * 8;

static constexpr void q22_check_static_vae() {
    static_assert(
        Q22_OUTPUT_HEIGHT == 512,
        "output height must be 512");
    static_assert(
        Q22_OUTPUT_WIDTH == 512,
        "output width must be 512");
    static_assert(
        zimage_sampler_512x512::Z9_LATENT ==
            zimage_vae_512x512::Z11_LATENT_CHANNELS *
            zimage_vae_512x512::Z11_HEIGHT *
            zimage_vae_512x512::Z11_WIDTH,
        "DiT and VAE latent shapes differ");
}

